{"path": "/app/quoter/services/cache.py", "content": """"Memoization of quote computations.

Batch files often repeat the same route and weight; quoting each one again is
wasted work. Results are kept for the life of the process, per Settings value:
a result is only reused for settings with the same field values it was
computed with.
"""

from __future__ import annotations

import functools
from dataclasses import fields

_STORE: dict = {}
_HITS = [0]


def _conf_key(conf) -> tuple:
    """What identifies a Settings value: the type and representation of every
    field, never the object itself. Representations are used because equal
    decimals such as 3.0 and 3.00 can still print differently."""
    return tuple((type(v).__name__, repr(v)) for v in (getattr(conf, f.name) for f in fields(conf)))


def memoized(fn):
    """Cache fn's results by its settings (the first argument, `conf`) and its
    other positional arguments, which must be hashable.

    Caching is skipped while the `cache_enabled` setting is off."""

    @functools.wraps(fn)
    def wrapper(conf, *args):
        if not conf.cache_enabled:
            return fn(conf, *args)
        key = (fn.__qualname__, _conf_key(conf)) + args
        if key in _STORE:
            _HITS[0] += 1
            return _STORE[key]
        value = fn(conf, *args)
        _STORE[key] = value
        return value

    return wrapper


def stats() -> tuple:
    """(entries, hits) since the process started."""
    return len(_STORE), _HITS[0]
"}

